package cn.iocoder.yudao.module.zsjos.dal.mysql.studentops; import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.studentops.CooperationAssessmentDO; import org.apache.ibatis.annotations.Mapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import java.util.List; @Mapper public interface CooperationAssessmentMapper extends BaseMapperX<CooperationAssessmentDO>{default List<CooperationAssessmentDO> selectByOperator(Long uid){return selectList(new LambdaQueryWrapper<CooperationAssessmentDO>().eq(CooperationAssessmentDO::getOperatorUserId,uid).orderByDesc(CooperationAssessmentDO::getAssessedAt));}}
